def compute(vars):
    securities = vars["v1"]
    price_per_security = vars["v2"]
    total_value = securities * price_per_security
    value_in_millions = total_value / 1000000

    return {
        "value": value_in_millions,
        "trace": {
            "securities": securities,
            "price_per_security": price_per_security,
            "total_value_in_ones": total_value,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
